1	{
2	  "name": "stockroom",
3	  "version": "0.0.0",
4	  "private": true,
5	  "type": "module",
6	  "engines": {
7	    "node": ">=24 <25"
8	  },
9	  "scripts": {
10	    "start": "node app.ts"
11	  },
12	  "bin": {
13	    "stockroom": "app.ts"
14	  }
15	}
16

1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType =
17	  | DocType
18	  | 'count'
19	  | 'arrival'
20	  | 'in-rev'
21	  | 'out-rev'
22	  | 'transfer-rev'
23	  | 'count-rev'
24	  | 'arrival-rev';
25	
26	interface LedgerEntry {
27	  seq: number; // 全局流水序号，即提交顺序
28	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
29	  type: EntryType;
30	  product: string;
31	  wh: string; // 本流水条目变动余量的仓库（到货为采购单收货仓）
32	  qty?: number; // 入库/出库/调拨/到货类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
33	  before: number;
34	  after: number;
35	  from?: string; // 调拨（或冲销调拨）的调出仓
36	  to?: string; // 调拨（或冲销调拨）的调入仓
37	  po?: string; // 到货流水：所属采购单编号
38	  orig?: string; // 冲销流水：被冲销的原单编号
39	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
40	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
41	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
42	}
43	
44	interface DocRecord {
45	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
46	  resultLines: string[]; // 原提交结果，供幂等重放
47	}
48	
49	interface ReversalRecord {
50	  orig: string; // 被冲销的原单编号
51	  resultLines: string[]; // 冲销提交结果，供幂等重放
52	}
53	
54	interface PurchaseRecord {
55	  poId: string;
56	  supplier: string;
57	  wh: string; // 收货仓
58	  ordered: Record<string, number>; // 商品 -> 订购量（合并后，正安全整数）
59	  resultLines: string[]; // 登记结果，供幂等重放
60	}
61	
62	interface ArrivalRecord {
63	  poId: string; // 所属采购单
64	  wh: string; // 采购单收货仓（冗余自采购单，便于校验与展示）
65	  qty: Record<string, number>; // 本次到货：商品 -> 数量（合并后，正安全整数）
66	  resultLines: string[]; // 到货提交结果，供幂等重放
67	}
68	
69	interface CancelRecord {
70	  poId: string; // 所属采购单
71	  qty: Record<string, number>; // 本次取消：商品 -> 数量（合并后，正安全整数）
72	  resultLines: string[]; // 取消提交结果，供幂等重放
73	}
74	
75	interface Store {
76	  version: 1;
77	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
78	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
79	  entries: LedgerEntry[];
80	  docs: Record<string, DocRecord>; // 入库/出库/调拨/盘点单去重与结果
81	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果（可冲销到货单、取消单）
82	  purchases: Record<string, PurchaseRecord>; // 采购单登记（独立编号空间，不改库存）
83	  arrivals: Record<string, ArrivalRecord>; // 到货单去重与结果（与库存单共用编号空间）
84	  cancels: Record<string, CancelRecord>; // 取消单去重与结果（与库存单共用编号空间，不改库存与流水）
85	}
86	
87	const REV_ENTRY_TYPES = new Set<EntryType>(['in-rev', 'out-rev', 'transfer-rev', 'count-rev', 'arrival-rev']);
88	
89	function nullProto<T extends object>(): T {
90	  return Object.create(null) as T;
91	}
92	
93	function emptyStore(): Store {
94	  return {
95	    version: 1,
96	    products: nullProto(),
97	    stock: nullProto(),
98	    entries: [],
99	    docs: nullProto(),
100	    reversals: nullProto(),
101	    purchases: nullProto(),
102	    arrivals: nullProto(),
103	    cancels: nullProto(),
104	  };
105	}
106	
107	// ---------- 工具 ----------
108	
109	function isPlainObject(v: unknown): v is Record<string, unknown> {
110	  return typeof v === 'object' && v !== null && !Array.isArray(v);
111	}
112	
113	function isNonNegSafeInt(v: unknown): v is number {
114	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
115	}
116	
117	function isPosSafeInt(v: unknown): v is number {
118	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
119	}
120	
121	function trimOrThrow(label: string, raw: string): string {
122	  const s = raw.trim();
123	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
124	  return s;
125	}
126	
127	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
128	function stableStringify(v: unknown): string {
129	  if (isPlainObject(v)) {
130	    return (
131	      '{' +
132	      Object.keys(v)
133	        .sort()
134	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
135	        .join(',') +
136	      '}'
137	    );
138	  }
139	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
140	  return JSON.stringify(v);
141	}
142	
143	// ---------- 数据持久化 ----------
144	
145	function dataPath(dataDir: string): string {
146	  return join(dataDir, DATA_FILENAME);
147	}
148	
149	function loadStore(dataDir: string): Store {
150	  let raw: string;
151	  try {
152	    raw = readFileSync(dataPath(dataDir), 'utf8');
153	  } catch (e) {
154	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
155	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
156	  }
157	
158	  let data: unknown;
159	  try {
160	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
161	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
162	    data = JSON.parse(raw);
163	  } catch {
164	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
165	  }
166	  return validateStore(data);
167	}
168	
169	function validateStore(data: unknown): Store {
170	  const bad = (msg: string): DataError =>
171	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
172	
173	  if (!isPlainObject(data)) throw bad('根节点不是对象');
174	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
175	
176	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
177	  const store = emptyStore();
178	
179	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
180	  for (const [id, name] of Object.entries(data.products)) {
181	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
182	      throw bad('products 中存在非法编号或名称');
183	    store.products[id] = name;
184	  }
185	
186	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
187	  for (const [pid, whs] of Object.entries(data.stock)) {
188	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
189	    const whMap = nullProto<Record<string, number>>();
190	    for (const [wh, qty] of Object.entries(whs)) {
191	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
192	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
193	      whMap[wh] = qty;
194	    }
195	    store.stock[pid] = whMap;
196	  }
197	
198	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
199	  let lastSeq = 0;
200	  for (const e of data.entries as unknown[]) {
201	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
202	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
203	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
204	    const isRev = REV_ENTRY_TYPES.has(e.type as EntryType);
205	    const isOrig =
206	      e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count' || e.type === 'arrival';
207	    if (!isRev && !isOrig) throw bad('流水类型非法');
208	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
209	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
210	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
211	    if (e.type === 'count' || e.type === 'count-rev') {
212	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
213	        throw bad('盘点流水账面/实盘量非法');
214	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
215	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
216	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
217	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
218	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined || e.po !== undefined)
219	        throw bad('盘点流水不应携带数量、调拨或采购字段');
220	    } else {
221	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
222	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
223	        throw bad('非盘点流水不应携带盘点字段');
224	      const delta = e.after - e.before;
225	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
226	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
227	          throw bad('调拨流水缺少调出/调入仓');
228	        if (e.po !== undefined) throw bad('调拨流水不应携带采购字段');
229	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
230	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
231	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
232	      } else {
233	        if (e.from !== undefined || e.to !== undefined) throw bad('非调拨流水不应携带调拨字段');
234	        // 到货入收货仓为增；冲销到货从收货仓扣回为减
235	        const increases = e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival';
236	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
237	        if (e.type === 'arrival' || e.type === 'arrival-rev') {
238	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('到货流水缺少采购单编号');
239	        } else if (e.po !== undefined) {
240	          throw bad('非到货流水不应携带采购字段');
241	        }
242	      }
243	    }
244	    if (isRev) {
245	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
246	    } else if (e.orig !== undefined) {
247	      throw bad('原始单据流水不应携带冲销标记');
248	    }
249	    store.entries.push(e as unknown as LedgerEntry);
250	  }
251	
252	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
253	  for (const [docId, rec] of Object.entries(data.docs)) {
254	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
255	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
256	      throw bad(`单据 ${docId} 的去重记录非法`);
257	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
258	    const c = rec.content;
259	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
260	      throw bad(`单据 ${docId} 的业务类型非法`);
261	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
262	    for (const [pid, item] of Object.entries(c.items)) {
263	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
264	      if (c.type === 'count') {
265	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
266	          throw bad(`单据 ${docId} 存在非法盘点明细`);
267	      } else if (!isPosSafeInt(item)) {
268	        throw bad(`单据 ${docId} 存在非法明细`);
269	      }
270	    }
271	    if (c.type === 'transfer') {
272	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
273	        throw bad(`单据 ${docId} 的调拨仓非法`);
274	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
275	      throw bad(`单据 ${docId} 的仓库非法`);
276	    }
277	    store.docs[docId] = rec as unknown as DocRecord;
278	  }
279	
280	  // purchases 为新增字段：合法旧数据没有该字段，按空集合处理。
281	  // 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名。
282	  if (data.purchases !== undefined) {
283	    if (!isPlainObject(data.purchases)) throw bad('purchases 不是对象');
284	    for (const [poId, rec] of Object.entries(data.purchases)) {
285	      if (typeof poId !== 'string' || poId.trim() === '') throw bad('存在非法采购单编号');
286	      if (
287	        !isPlainObject(rec) ||
288	        typeof rec.supplier !== 'string' || rec.supplier.trim() === '' ||
289	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
290	        !isPlainObject(rec.ordered) ||
291	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
292	      )
293	        throw bad(`采购单 ${poId} 的记录非法`);
294	      if (rec.poId !== undefined && rec.poId !== poId) throw bad(`采购单 ${poId} 的内嵌编号不一致`);
295	      const ordered = nullProto<Record<string, number>>();
296	      for (const [pid, qty] of Object.entries(rec.ordered)) {
297	        if (pid.trim() === '' || !isPosSafeInt(qty)) throw bad(`采购单 ${poId} 存在非法订购明细`);
298	        ordered[pid] = qty;
299	      }
300	      if (Object.keys(ordered).length === 0) throw bad(`采购单 ${poId} 至少需要一种商品`);
301	      store.purchases[poId] = {
302	        poId, supplier: rec.supplier, wh: rec.wh, ordered, resultLines: rec.resultLines,
303	      };
304	    }
305	  }
306	
307	  // arrivals 为新增字段：合法旧数据没有该字段，按空集合处理。
308	  // 到货单与入库/出库/调拨/盘点/冲销单共用全局唯一编号空间。
309	  if (data.arrivals !== undefined) {
310	    if (!isPlainObject(data.arrivals)) throw bad('arrivals 不是对象');
311	    for (const [arrId, rec] of Object.entries(data.arrivals)) {
312	      if (typeof arrId !== 'string' || arrId.trim() === '') throw bad('存在非法到货单编号');
313	      if (store.docs[arrId] !== undefined) throw bad(`到货单编号 ${arrId} 与原始库存单据编号冲突`);
314	      if (
315	        !isPlainObject(rec) ||
316	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
317	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
318	        !isPlainObject(rec.qty) ||
319	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
320	      )
321	        throw bad(`到货单 ${arrId} 的记录非法`);
322	      const qty = nullProto<Record<string, number>>();
323	      for (const [pid, q] of Object.entries(rec.qty)) {
324	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`到货单 ${arrId} 存在非法到货明细`);
325	        qty[pid] = q;
326	      }
327	      if (Object.keys(qty).length === 0) throw bad(`到货单 ${arrId} 至少需要一种商品`);
328	      const po = store.purchases[rec.poId];
329	      if (po === undefined) throw bad(`到货单 ${arrId} 指向的采购单 ${rec.poId} 不存在`);
330	      if (rec.wh !== po.wh) throw bad(`到货单 ${arrId} 的收货仓与采购单 ${rec.poId} 不一致`);
331	      for (const [pid, q] of Object.entries(qty)) {
332	        if (po.ordered[pid] === undefined)
333	          throw bad(`到货单 ${arrId} 含采购单 ${rec.poId} 未订购的商品 ${pid}`);
334	        if (q > po.ordered[pid])
335	          throw bad(`到货单 ${arrId} 商品 ${pid} 到货量超过订购量`);
336	      }
337	      store.arrivals[arrId] = { poId: rec.poId, wh: rec.wh, qty, resultLines: rec.resultLines };
338	    }
339	  }
340	
341	  // cancels 为新增字段：合法旧数据没有该字段，按空集合处理。
342	  // 取消单与入库/出库/调拨/盘点/到货/冲销单共用全局唯一编号空间；
343	  // 取消只减少待收承诺，不改库存、不产生库存流水。
344	  if (data.cancels !== undefined) {
345	    if (!isPlainObject(data.cancels)) throw bad('cancels 不是对象');
346	    for (const [canId, rec] of Object.entries(data.cancels)) {
347	      if (typeof canId !== 'string' || canId.trim() === '') throw bad('存在非法取消单编号');
348	      if (store.docs[canId] !== undefined) throw bad(`取消单编号 ${canId} 与原始库存单据编号冲突`);
349	      if (store.arrivals[canId] !== undefined) throw bad(`取消单编号 ${canId} 与到货单编号冲突`);
350	      if (
351	        !isPlainObject(rec) ||
352	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
353	        !isPlainObject(rec.qty) ||
354	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
355	      )
356	        throw bad(`取消单 ${canId} 的记录非法`);
357	      const qty = nullProto<Record<string, number>>();
358	      for (const [pid, q] of Object.entries(rec.qty)) {
359	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`取消单 ${canId} 存在非法取消明细`);
360	        qty[pid] = q;
361	      }
362	      if (Object.keys(qty).length === 0) throw bad(`取消单 ${canId} 至少需要一种商品`);
363	      const po = store.purchases[rec.poId];
364	      if (po === undefined) throw bad(`取消单 ${canId} 指向的采购单 ${rec.poId} 不存在`);
365	      for (const [pid, q] of Object.entries(qty)) {
366	        if (po.ordered[pid] === undefined)
367	          throw bad(`取消单 ${canId} 含采购单 ${rec.poId} 未订购的商品 ${pid}`);
368	        if (q > po.ordered[pid])
369	          throw bad(`取消单 ${canId} 商品 ${pid} 取消量超过订购量`);
370	      }
371	      store.cancels[canId] = { poId: rec.poId, qty, resultLines: rec.resultLines };
372	    }
373	  }
374	
375	  // reversals 为新增字段：合法旧数据没有该字段，按空集合处理。
376	  // 原单既可以是入库/出库/调拨/盘点单，也可以是到货单、取消单；冲销单不可冲销。
377	  if (data.reversals !== undefined) {
378	    if (!isPlainObject(data.reversals)) throw bad('reversals 不是对象');
379	    for (const [revId, rec] of Object.entries(data.reversals)) {
380	      if (typeof revId !== 'string' || revId.trim() === '') throw bad('存在非法冲销单编号');
381	      if (!isPlainObject(rec) || typeof rec.orig !== 'string' || rec.orig.trim() === '' ||
382	          !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string'))
383	        throw bad(`冲销单 ${revId} 的记录非法`);
384	      if (store.docs[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与原始库存单据编号冲突`);
385	      if (store.arrivals[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与到货单编号冲突`);
386	      if (store.cancels[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与取消单编号冲突`);
387	      const origRec = store.docs[rec.orig];
388	      const origArr = store.arrivals[rec.orig];
389	      const origCan = store.cancels[rec.orig];
390	      if (origRec === undefined && origArr === undefined && origCan === undefined) {
391	        // 用 data.reversals 判定，避免依赖键的先后顺序（此时 store.reversals 可能尚未装全）
392	        if (isPlainObject((data.reversals as Record<string, unknown>)[rec.orig]))
393	          throw bad(`冲销单 ${rec.orig} 不可被再次冲销（冲销单不能冲销冲销单）`);
394	        if (store.purchases[rec.orig] !== undefined)
395	          throw bad(`冲销单 ${revId} 指向的 ${rec.orig} 是采购单，采购单不可冲销`);
396	        throw bad(`冲销单 ${revId} 指向的原单 ${rec.orig} 不存在`);
397	      }
398	      store.reversals[revId] = { orig: rec.orig, resultLines: rec.resultLines };
399	    }
400	    // 每张原单最多被成功冲销一次（库存单与到货单统一校验）
401	    const origSeen = nullProto<Record<string, string>>();
402	    for (const [revId, rec] of Object.entries(store.reversals)) {
403	      if (origSeen[rec.orig] !== undefined)
404	        throw bad(`原单 ${rec.orig} 被多张冲销单关联（${origSeen[rec.orig]}、${revId}）`);
405	      origSeen[rec.orig] = revId;
406	    }
407	    // 冲销单不可冲销：冲销关系不能指向另一张冲销单
408	    for (const rec of Object.values(store.reversals)) {
409	      if (store.reversals[rec.orig] !== undefined)
410	        throw bad(`冲销单 ${rec.orig} 不可被再次冲销`);
411	    }
412	    // 冲销流水必须能找到所属冲销单
413	    for (const e of store.entries) {
414	      if (REV_ENTRY_TYPES.has(e.type) && store.reversals[e.doc] === undefined)
415	        throw bad(`流水引用了不存在的冲销单 ${e.doc}`);
416	    }
417	  }
418	
419	  // 到货流水必须能找到所属到货单，且逐项数量/采购单/收货仓与记录一致
420	  const arrivalEntrySeen = nullProto<Record<string, Record<string, number>>>();
421	  for (const e of store.entries) {
422	    if (e.type !== 'arrival') continue;
423	    const arr = store.arrivals[e.doc];
424	    if (arr === undefined) throw bad(`流水引用了不存在的到货单 ${e.doc}`);
425	    if (e.po !== arr.poId) throw bad(`到货单 ${e.doc} 流水的采购单编号与记录不一致`);
426	    if (e.wh !== arr.wh) throw bad(`到货单 ${e.doc} 流水的收货仓与记录不一致`);
427	    const perProduct = (arrivalEntrySeen[e.doc] ??= nullProto<Record<string, number>>());
428	    perProduct[e.product] = (perProduct[e.product] ?? 0) + e.qty!;
429	  }
430	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
431	    const seen = arrivalEntrySeen[arrId];
432	    if (seen === undefined) throw bad(`到货单 ${arrId} 缺少到货流水`);
433	    for (const [pid, q] of Object.entries(arr.qty)) {
434	      if (seen[pid] !== q) throw bad(`到货单 ${arrId} 商品 ${pid} 的流水数量与记录不一致`);
435	    }
436	    for (const pid of Object.keys(seen)) {
437	      if (arr.qty[pid] === undefined) throw bad(`到货单 ${arrId} 的流水含记录中没有的商品 ${pid}`);
438	    }
439	  }
440	
441	  // 冲销到货流水逐项数量必须与原到货单一致
442	  for (const e of store.entries) {
443	    if (e.type !== 'arrival-rev') continue;
444	    const rev = store.reversals[e.doc];
445	    if (rev === undefined) throw bad(`冲销到货流水引用了不存在的冲销单 ${e.doc}`);
446	    const arr = store.arrivals[rev.orig];
447	    if (arr === undefined) throw bad(`冲销单 ${e.doc} 指向的到货原单 ${rev.orig} 不存在`);
448	    if (e.po !== arr.poId) throw bad(`冲销单 ${e.doc} 流水的采购单编号与原到货单不一致`);
449	    if (arr.qty[e.product] !== e.qty)
450	      throw bad(`冲销单 ${e.doc} 商品 ${e.product} 的冲销量与原到货单不一致`);
451	  }
452	
453	  // 冲销流水类型必须与原单业务类型一致（入库→in-rev、到货→arrival-rev 等）；
454	  // 取消单冲销不产生库存流水（取消本身不改库存），故不要求、也不允许携带流水。
455	  const revIdsWithEntries = nullProto<Record<string, boolean>>();
456	  for (const [revId, rev] of Object.entries(store.reversals)) {
457	    const origDoc = store.docs[rev.orig];
458	    const isCancelOrig = origDoc === undefined && store.arrivals[rev.orig] === undefined;
459	    // 原单为取消单时（前面已确认三者必居其一）不应存在任何冲销流水
460	    let expected: EntryType | undefined;
461	    if (origDoc !== undefined) expected = `${origDoc.content.type}-rev` as EntryType;
462	    else if (!isCancelOrig) expected = 'arrival-rev';
463	    for (const e of store.entries) {
464	      if (e.doc !== revId) continue;
465	      if (expected === undefined)
466	        throw bad(`冲销单 ${revId} 冲销的是取消单 ${rev.orig}，不应携带库存流水`);
467	      revIdsWithEntries[revId] = true;
468	      if (e.type !== expected)
469	        throw bad(`冲销单 ${revId} 的流水类型与原单 ${rev.orig} 的业务类型不一致`);
470	    }
471	    if (expected !== undefined) revIdsWithEntries[revId] ??= false;
472	  }
473	  for (const revId of Object.keys(store.reversals)) {
474	    if (revIdsWithEntries[revId] === false) throw bad(`冲销单 ${revId} 缺少冲销流水`);
475	  }
476	
477	  // 采购进度不变量：任一商品“未冲销累计到货 + 未冲销累计取消”不得超过订购量
478	  // （待到货量 = 订购量 - 有效到货量 - 有效取消量，不得为负）。
479	  for (const [poId, po] of Object.entries(store.purchases)) {
480	    const arrived = nullProto<Record<string, number>>();
481	    for (const [arrId, arr] of Object.entries(store.arrivals)) {
482	      if (arr.poId !== poId) continue;
483	      const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
484	      if (isReversed) continue; // 已整单冲销的到货不再计入有效到货
485	      for (const [pid, q] of Object.entries(arr.qty)) {
486	        arrived[pid] = (arrived[pid] ?? 0) + q;
487	        if (arrived[pid] > po.ordered[pid])
488	          throw bad(`采购单 ${poId} 商品 ${pid} 未冲销累计到货超过订购量`);
489	      }
490	    }
491	    const cancelled = nullProto<Record<string, number>>();
492	    for (const [canId, can] of Object.entries(store.cancels)) {
493	      if (can.poId !== poId) continue;
494	      const isReversed = Object.values(store.reversals).some((r) => r.orig === canId);
495	      if (isReversed) continue; // 已整单冲销的取消不再计入有效取消
496	      for (const [pid, q] of Object.entries(can.qty)) {
497	        cancelled[pid] = (cancelled[pid] ?? 0) + q;
498	        if ((arrived[pid] ?? 0) + cancelled[pid] > po.ordered[pid])
499	          throw bad(`采购单 ${poId} 商品 ${pid} 有效到货与有效取消合计超过订购量（待到货量为负）`);
500	      }
501	    }
502	  }
503	
504	  return store;
505	}
