507	function saveStore(dataDir: string, store: Store): void {
508	  const path = dataPath(dataDir);
509	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
510	  try {
511	    mkdirSync(dataDir, { recursive: true });
512	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
513	    renameSync(tmp, path);
514	  } catch (e) {
515	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
516	  }
517	}
