519	// ---------- 参数解析 ----------
520	
521	interface ParsedArgs {
522	  positionals: string[];
523	  flags: Record<string, string>;
524	  multi: Record<string, string[]>;
525	}
526	
527	function parseArgs(
528	  tokens: string[],
529	  singles: string[],
530	  multis: string[] = [],
531	): ParsedArgs {
532	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
533	  const singleSet = new Set(singles);
534	  const multiSet = new Set(multis);
535	
536	  for (let i = 0; i < tokens.length; i++) {
537	    const tok = tokens[i];
538	    if (tok.startsWith('--')) {
539	      let key = tok;
540	      let value: string | undefined;
541	      const eq = tok.indexOf('=');
542	      if (eq >= 0) {
543	        key = tok.slice(0, eq);
544	        value = tok.slice(eq + 1);
545	      }
546	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
547	      if (value === undefined) {
548	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
549	        value = tokens[++i];
550	      }
551	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
552	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
553	      else out.flags[key] = value;
554	    } else {
555	      out.positionals.push(tok);
556	    }
557	  }
558	  return out;
559	}
560	
561	function parseItem(raw: string, merged: Map<string, number>): void {
562	  const idx = raw.indexOf(':');
563	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
564	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
565	  const qtyRaw = raw.slice(idx + 1).trim();
566	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
567	  const qty = Number(qtyRaw);
568	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
569	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
570	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
571	  merged.set(pid, sum);
572	}
