574	interface DocRequest {
575	  type: DocType;
576	  docId: string;
577	  wh?: string;
578	  from?: string;
579	  to?: string;
580	  items: Map<string, number>;
581	}
582	
583	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
584	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
585	  const docId = args.positionals[0];
586	  if (docId === undefined || args.positionals.length !== 1)
587	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
588	
589	  const items = new Map<string, number>();
590	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
591	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
592	
593	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
594	  if (type === 'transfer') {
595	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
596	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
597	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
598	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
599	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
600	  } else {
601	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
602	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
603	  }
604	  return req;
605	}
606	
607	interface CountItem {
608	  expected: number; // 预期账面量
609	  actual: number; // 实盘量
610	}
611	
612	interface CountRequest {
613	  docId: string;
614	  wh: string;
615	  items: Map<string, CountItem>;
616	}
617	
618	function parseNonNegInt(label: string, raw: string): number {
619	  const s = raw.trim();
620	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
621	  const n = Number(s);
622	  if (!Number.isSafeInteger(n)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
623	  return n;
624	}
625	
626	function parseCountArgs(tokens: string[]): CountRequest {
627	  const args = parseArgs(tokens, ['--wh'], ['--item']);
628	  const docId = args.positionals[0];
629	  if (docId === undefined || args.positionals.length !== 1)
630	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
631	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
632	
633	  const items = new Map<string, CountItem>();
634	  for (const raw of args.multi['--item'] ?? []) {
635	    const parts = raw.split(':');
636	    if (parts.length !== 3)
637	      throw new BizError(`盘点明细格式应为 “商品编号:预期账面量:实盘量”：${raw}`);
638	    const pid = trimOrThrow('商品编号', parts[0]);
639	    const expected = parseNonNegInt(`商品 ${pid} 的预期账面量`, parts[1]);
640	    const actual = parseNonNegInt(`商品 ${pid} 的实盘量`, parts[2]);
641	    if (items.has(pid)) throw new BizError(`盘点单中商品 ${pid} 重复出现，拒绝提交`);
642	    items.set(pid, { expected, actual });
643	  }
644	  if (items.size === 0)
645	    throw new UsageError('盘点单至少需要一条 --item 商品编号:预期账面量:实盘量 明细');
646	
647	  return { docId: trimOrThrow('单据编号', docId), wh: trimOrThrow('仓库标识', args.flags['--wh']), items };
648	}
