671	function parsePurchaseArgs(tokens: string[]): PurchaseRequest {
672	  const args = parseArgs(tokens, ['--supplier', '--wh'], ['--item']);
673	  const poRaw = args.positionals[0];
674	  if (poRaw === undefined || args.positionals.length !== 1)
675	    throw new UsageError('用法：po register <采购编号> --supplier <供应商名称> --wh <收货仓> --item <商品编号:订购量> [...]');
676	  if (args.flags['--supplier'] === undefined) throw new UsageError('采购单必须提供 --supplier <供应商名称>');
677	  if (args.flags['--wh'] === undefined) throw new UsageError('采购单必须提供 --wh <收货仓>');
