681	  if (items.size === 0) throw new UsageError('采购单至少需要一条 --item 商品编号:订购量 明细');
682	
683	  return {
684	    poId: trimOrThrow('采购编号', poRaw),
685	    supplier: trimOrThrow('供应商名称', args.flags['--supplier']),
686	    wh: trimOrThrow('收货仓标识', args.flags['--wh']),
687	    items,
688	  };
689	}
