695	    throw new UsageError('用法：arrival <到货单编号> --po <采购编号> --item <商品编号:到货量> [...]');
696	  if (args.flags['--po'] === undefined) throw new UsageError('到货必须通过 --po <采购编号> 指定所属采购单（收货仓取采购单）');
697	
698	  const items = new Map<string, number>();
699	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
700	  if (items.size === 0) throw new UsageError('到货单至少需要一条 --item 商品编号:到货量 明细');
701	
702	  return { arrId: trimOrThrow('到货单编号', arrRaw), poId: trimOrThrow('采购编号', args.flags['--po']), items };
703	}
