705	function parseCancelArgs(tokens: string[]): CancelRequest {
706	  const args = parseArgs(tokens, ['--po'], ['--item']);
707	  const canRaw = args.positionals[0];
708	  if (canRaw === undefined || args.positionals.length !== 1)
709	    throw new UsageError('用法：cancel <取消单编号> --po <采购编号> --item <商品编号:取消量> [...]');
710	  if (args.flags['--po'] === undefined) throw new UsageError('取消必须通过 --po <采购编号> 指定所属采购单');
711	
