719	// ---------- 整批导入文件解析 ----------
720	
721	type ImportRequest =
722	  | { kind: 'doc'; req: DocRequest }
723	  | { kind: 'count'; req: CountRequest }
724	  | { kind: 'reverse'; docId: string; orig: string }
725	  | { kind: 'po'; req: PurchaseRequest }
726	  | { kind: 'arrival'; req: ArrivalRequest }
727	  | { kind: 'cancel'; req: CancelRequest };
728	
729	/** 读取导入文件：无法读取属于读写失败（退出 1），不改变任何已提交状态。 */
730	function readImportFile(file: string): string {
731	  try {
732	    return readFileSync(file, 'utf8');
733	  } catch (e) {
734	    throw new DataError(`无法读取导入文件 ${file}：${(e as Error).message}（不会改变任何已提交数据）`);
735	  }
736	}
737	
738	/**
739	 * 解析整批导入文件。文件级结构错误（非合法 JSON、根不是数组、空列表）属于文件
740	 * 格式错误（退出 2）；逐项格式不合法属于业务拒绝（退出 1），指出位置与原因。
741	 */
742	function parseImportFile(raw: string): ImportRequest[] {
743	  let data: unknown;
744	  try {
745	    data = JSON.parse(raw);
746	  } catch (e) {
747	    throw new UsageError(`导入文件不是合法 JSON：${(e as Error).message}`);
748	  }
749	  if (!Array.isArray(data)) throw new UsageError('导入文件格式错误：根节点必须是单据对象组成的有序数组');
750	  if (data.length === 0) throw new UsageError('导入文件格式错误：单据列表至少包含一项');
751	
752	  const out: ImportRequest[] = [];
753	  // 顶层位置一律标注 1 起序号，便于纠正
754	  const at = (i: number, msg: string): BizError => new BizError(`第 ${i + 1} 项：${msg}`);
755	
756	  const requireString = (obj: Record<string, unknown>, key: string, label: string, i: number): string => {
757	    const v = obj[key];
758	    if (v === undefined) throw at(i, `缺少${label}字段 "${key}"`);
759	    if (typeof v !== 'string') throw at(i, `${label}字段 "${key}" 必须是字符串`);
760	    const s = v.trim();
761	    if (s === '') throw at(i, `${label}去除首尾空白后不能为空`);
762	    return s;
763	  };
764	
765	  const checkUnknown = (obj: Record<string, unknown>, allowed: readonly string[], i: number): void => {
766	    for (const k of Object.keys(obj)) {
767	      if (!allowed.includes(k)) throw at(i, `含不支持的字段 "${k}"（允许字段：${allowed.join('、')}）`);
768	    }
769	  };
770	
771	  const parseQtyItems = (obj: Record<string, unknown>, i: number): Map<string, number> => {
772	    const v = obj.items;
773	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
774	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
775	    if (v.length === 0) throw at(i, '商品明细至少一项');
776	    const merged = new Map<string, number>();
777	    v.forEach((entry, j) => {
778	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
779	      const e = entry as Record<string, unknown>;
780	      checkUnknown(e, ['product', 'qty'], i);
781	      const pid = e.product;
782	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
783	      const p = pid.trim();
784	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
785	      if (!isPosSafeInt(e.qty)) throw at(i, `商品 ${p} 的数量必须为正安全整数`);
786	      const sum = (merged.get(p) ?? 0) + (e.qty as number); // 同单同商品先合并
787	      if (!Number.isSafeInteger(sum)) throw at(i, `商品 ${p} 累计数量超出安全整数范围`);
788	      merged.set(p, sum);
789	    });
790	    return merged;
791	  };
792	
793	  const parseCountItems = (obj: Record<string, unknown>, i: number): Map<string, CountItem> => {
794	    const v = obj.items;
795	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
796	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
797	    if (v.length === 0) throw at(i, '商品明细至少一项');
798	    const items = new Map<string, CountItem>();
799	    v.forEach((entry, j) => {
800	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
801	      const e = entry as Record<string, unknown>;
802	      checkUnknown(e, ['product', 'expected', 'actual'], i);
803	      const pid = e.product;
804	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
805	      const p = pid.trim();
806	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
807	      if (!isNonNegSafeInt(e.expected)) throw at(i, `商品 ${p} 的预期账面量必须为非负安全整数`);
808	      if (!isNonNegSafeInt(e.actual)) throw at(i, `商品 ${p} 的实盘量必须为非负安全整数`);
809	      if (items.has(p)) throw at(i, `盘点明细中商品 ${p} 重复出现，拒绝提交`); // 盘点不合并
810	      items.set(p, { expected: e.expected, actual: e.actual });
811	    });
812	    return items;
813	  };
814	
815	  data.forEach((rawItem, i) => {
816	    if (!isPlainObject(rawItem)) throw at(i, '不是单据对象');
817	    const item = rawItem as Record<string, unknown>;
818	    if (item.type === undefined) throw at(i, '缺少业务类型字段 "type"');
819	    if (typeof item.type !== 'string') throw at(i, '业务类型字段 "type" 必须是字符串');
820	
821	    switch (item.type) {
822	      case 'in':
823	      case 'out': {
824	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
825	        const docId = requireString(item, 'id', '单据编号', i);
826	        const wh = requireString(item, 'wh', '仓库标识', i);
827	        out.push({ kind: 'doc', req: { type: item.type, docId, wh, items: parseQtyItems(item, i) } });
828	        break;
829	      }
830	      case 'transfer': {
831	        checkUnknown(item, ['type', 'id', 'from', 'to', 'items'], i);
832	        const docId = requireString(item, 'id', '单据编号', i);
833	        const from = requireString(item, 'from', '调出仓标识', i);
834	        const to = requireString(item, 'to', '调入仓标识', i);
835	        if (from === to) throw at(i, '调拨单的调出仓与调入仓不能相同');
836	        out.push({ kind: 'doc', req: { type: 'transfer', docId, from, to, items: parseQtyItems(item, i) } });
837	        break;
838	      }
839	      case 'count': {
840	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
841	        const docId = requireString(item, 'id', '单据编号', i);
842	        const wh = requireString(item, 'wh', '仓库标识', i);
843	        out.push({ kind: 'count', req: { docId, wh, items: parseCountItems(item, i) } });
844	        break;
845	      }
846	      case 'reverse': {
847	        checkUnknown(item, ['type', 'id', 'orig'], i);
848	        const docId = requireString(item, 'id', '冲销单编号', i);
849	        const orig = requireString(item, 'orig', '原单编号', i);
850	        out.push({ kind: 'reverse', docId, orig });
851	        break;
852	      }
853	      case 'po': {
854	        checkUnknown(item, ['type', 'id', 'supplier', 'wh', 'items'], i);
855	        const poId = requireString(item, 'id', '采购编号', i);
856	        const supplier = requireString(item, 'supplier', '供应商名称', i);
857	        const wh = requireString(item, 'wh', '收货仓标识', i);
858	        out.push({ kind: 'po', req: { poId, supplier, wh, items: parseQtyItems(item, i) } });
859	        break;
860	      }
861	      case 'arrival': {
862	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
863	        const arrId = requireString(item, 'id', '到货单编号', i);
864	        const poId = requireString(item, 'po', '采购编号', i);
865	        out.push({ kind: 'arrival', req: { arrId, poId, items: parseQtyItems(item, i) } });
866	        break;
867	      }
868	      case 'cancel': {
869	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
870	        const canId = requireString(item, 'id', '取消单编号', i);
871	        const poId = requireString(item, 'po', '采购编号', i);
872	        out.push({ kind: 'cancel', req: { canId, poId, items: parseQtyItems(item, i) } });
873	        break;
874	      }
875	      default:
876	        throw at(i, `不支持的业务类型 "${String(item.type)}"，只允许 in、out、transfer、count、reverse、po、arrival、cancel`);
877	    }
878	  });
879	
880	  return out;
881	}
