883	// ---------- 业务核心 ----------
884	
885	const MAX_SAFE = Number.MAX_SAFE_INTEGER;
886	
887	/** 带符号数量文本：正数加 +，负数保留 -，零为 0。 */
888	function fmtSigned(n: number): string {
889	  return n > 0 ? `+${n}` : String(n);
890	}
891	
892	function canonicalContent(req: DocRequest): Record<string, unknown> {
893	  const items: Record<string, number> = nullProto();
894	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
895	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
896	  return { type: req.type, wh: req.wh!, items };
897	}
898	
899	function getStock(stock: Store['stock'], pid: string, wh: string): number {
900	  return stock[pid]?.[wh] ?? 0;
901	}
902	
903	function setStock(stock: Store['stock'], pid: string, wh: string, qty: number): void {
904	  (stock[pid] ??= nullProto<Record<string, number>>())[wh] = qty;
905	}
906	
907	/**
908	 * 深拷贝余量草稿。必须自建 null 原型容器：structuredClone 不保留 null 原型，
909	 * 普通对象在 "__proto__"/"constructor" 等商品或仓库键下会发生原型串改。
910	 */
911	function cloneStock(stock: Store['stock']): Store['stock'] {
912	  const out = nullProto<Store['stock']>();
913	  for (const pid of Object.keys(stock)) {
914	    const whMap = nullProto<Record<string, number>>();
915	    for (const wh of Object.keys(stock[pid])) whMap[wh] = stock[pid][wh];
916	    out[pid] = whMap;
917	  }
918	  return out;
919	}
920	
921	function canonicalCountContent(req: CountRequest): Record<string, unknown> {
922	  const items: Record<string, unknown> = nullProto();
923	  for (const pid of [...req.items.keys()].sort()) {
924	    const it = req.items.get(pid)!;
925	    items[pid] = { expected: it.expected, actual: it.actual };
926	  }
927	  return { type: 'count', wh: req.wh, items };
928	}
929	
930	/** 采购单规范化内容：明细按商品编号排序，比较时与明细顺序无关。 */
931	function canonicalPurchaseContent(req: PurchaseRequest): {
932	  supplier: string;
933	  wh: string;
934	  ordered: Record<string, number>;
935	} {
936	  const ordered: Record<string, number> = nullProto();
937	  for (const pid of [...req.items.keys()].sort()) ordered[pid] = req.items.get(pid)!;
938	  return { supplier: req.supplier, wh: req.wh, ordered };
939	}
940	
941	/** 到货明细规范化：合并后数量按商品编号排序。 */
942	function canonicalArrivalItems(items: Map<string, number>): Record<string, number> {
943	  const out: Record<string, number> = nullProto();
944	  for (const pid of [...items.keys()].sort()) out[pid] = items.get(pid)!;
945	  return out;
946	}
947	
948	interface ApplyOutcome {
949	  duplicate: boolean;
950	  header: string; // 结果首行汇总
951	  lines: string[]; // 逐项明细结果
952	  repeatedFrom?: 'store' | 'batch'; // 重复项来自导入前已存数据，还是本批此前各项
953	}
954	
955	/**
956	 * 账务模拟器：单条命令与整批导入共用。所有变动先落在草稿余量与新增流水上，
957	 * 编号去重视图（docs/revs）在模拟期间即时更新但不写回 base，全部项通过后由
958	 * commit 一次性落库；模拟途中抛错则 base 与磁盘均不受影响。
959	 */
960	class Ledger {
961	  private readonly base: Store;
962	  private readonly draft: Store['stock'];
963	  private readonly additions: LedgerEntry[] = [];
964	  private seq: number;
965	  private readonly docs: Record<string, DocRecord> = nullProto();
966	  private readonly revs: Record<string, ReversalRecord> = nullProto();
967	  private readonly pos: Record<string, PurchaseRecord> = nullProto();
968	  private readonly arrivals: Record<string, ArrivalRecord> = nullProto();
969	  private readonly cancels: Record<string, CancelRecord> = nullProto();
970	  private readonly reversedOrigs = new Set<string>();
971	  private readonly newDocIds: string[] = [];
972	  private readonly newRevIds: string[] = [];
973	  private readonly newPoIds: string[] = [];
974	  private readonly newArrivalIds: string[] = [];
975	  private readonly newCancelIds: string[] = [];
976	
977	  constructor(store: Store) {
978	    this.base = store;
979	    this.draft = cloneStock(store.stock);
980	    this.seq = store.entries.length;
981	    for (const [id, rec] of Object.entries(store.docs)) this.docs[id] = rec;
982	    for (const [id, rec] of Object.entries(store.reversals)) {
983	      this.revs[id] = rec;
984	      this.reversedOrigs.add(rec.orig);
985	    }
986	    for (const [id, rec] of Object.entries(store.purchases)) this.pos[id] = rec;
987	    for (const [id, rec] of Object.entries(store.arrivals)) this.arrivals[id] = rec;
988	    for (const [id, rec] of Object.entries(store.cancels)) this.cancels[id] = rec;
989	  }
990	
991	  /** 是否有新生效单据：无新单据（全部重复）时 commit 不改写数据。 */
992	  get changed(): boolean {
993	    return (
994	      this.newDocIds.length +
995	      this.newRevIds.length +
996	      this.newPoIds.length +
997	      this.newArrivalIds.length +
998	      this.newCancelIds.length > 0
999	    );
1000	  }
1001	
1002	  /** 重建原始单据结果首行，供幂等重放。 */
1003	  private docHeader(docId: string, rec: DocRecord): string {
1004	    const c = rec.content;
1005	    const n = Object.keys(c.items as Record<string, unknown>).length;
1006	    return c.type === 'count'
1007	      ? `盘点单 ${docId} 提交成功，仓库 ${c.wh as string}，共 ${n} 种商品：`
1008	      : `${c.type === 'in' ? '入库' : c.type === 'out' ? '出库' : '调拨'}单 ${docId} 提交成功，共 ${n} 种商品：`;
1009	  }
1010	
1011	  /** 重建冲销单结果首行，供幂等重放。 */
1012	  private revHeader(revId: string, rec: ReversalRecord): string {
1013	    const origDoc = this.docs[rec.orig];
1014	    if (origDoc !== undefined) {
1015	      const type = origDoc.content.type as string;
1016	      const label = type === 'in' ? '入库' : type === 'out' ? '出库' : type === 'transfer' ? '调拨' : '盘点';
1017	      const n = Object.keys(origDoc.content.items as Record<string, unknown>).length;
1018	      return `冲销单 ${revId} 提交成功，冲销${label}原单 ${rec.orig}，共 ${n} 种商品：`;
1019	    }
1020	    const origCan = this.cancels[rec.orig];
1021	    if (origCan !== undefined) {
1022	      const n = Object.keys(origCan.qty).length;
1023	      return `冲销单 ${revId} 提交成功，冲销取消原单 ${rec.orig}（采购单 ${origCan.poId}），共 ${n} 种商品：`;
1024	    }
1025	    // 原单为到货单（能进入去重视图的冲销单必然指向存在的原单）
1026	    const arr = this.arrivals[rec.orig];
1027	    const n = Object.keys(arr.qty).length;
1028	    return `冲销单 ${revId} 提交成功，冲销到货原单 ${rec.orig}（采购单 ${arr.poId}），共 ${n} 种商品：`;
1029	  }
1030	
1031	  private repeatedPoSource(poId: string): 'store' | 'batch' {
1032	    return this.base.purchases[poId] !== undefined ? 'store' : 'batch';
1033	  }
1034	
1035	  private repeatedArrivalSource(arrId: string): 'store' | 'batch' {
1036	    return this.base.arrivals[arrId] !== undefined ? 'store' : 'batch';
1037	  }
1038	
1039	  /** 计算某采购单各商品当前“未冲销累计到货”（仅计入尚未被整单冲销的到货单）。 */
1040	  private effectiveArrived(poId: string): Record<string, number> {
1041	    const arrived = nullProto<Record<string, number>>();
1042	    for (const [arrId, arr] of Object.entries(this.arrivals)) {
1043	      if (arr.poId !== poId || this.reversedOrigs.has(arrId)) continue;
1044	      for (const [pid, q] of Object.entries(arr.qty)) arrived[pid] = (arrived[pid] ?? 0) + q;
1045	    }
1046	    return arrived;
1047	  }
1048	
1049	  /** 计算某采购单各商品当前“未冲销累计取消”（仅计入尚未被整单冲销的取消单）。 */
1050	  private effectiveCancelled(poId: string): Record<string, number> {
1051	    const cancelled = nullProto<Record<string, number>>();
1052	    for (const [canId, can] of Object.entries(this.cancels)) {
1053	      if (can.poId !== poId || this.reversedOrigs.has(canId)) continue;
1054	      for (const [pid, q] of Object.entries(can.qty)) cancelled[pid] = (cancelled[pid] ?? 0) + q;
1055	    }
1056	    return cancelled;
1057	  }
1058	
1059	  /**
1060	   * 采购单登记：只登记订购信息，不改动任何库存，登记成功后内容不可修改。
1061	   * 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名；
1062	   * 同号同内容重放返回原登记结果且不重置到货进度，同号不同内容拒绝。
1063	   */
1064	  applyPurchase(req: PurchaseRequest): ApplyOutcome {
1065	    const content = canonicalPurchaseContent(req);
1066	    const existed = this.pos[req.poId];
1067	    if (existed !== undefined) {
1068	      if (
1069	        existed.supplier !== req.supplier ||
1070	        existed.wh !== req.wh ||
1071	        stableStringify(existed.ordered) !== stableStringify(content.ordered as Record<string, number>)
1072	      )
1073	        throw new BizError(`采购编号 ${req.poId} 已用于内容不同的采购单，拒绝提交且不重置到货进度`);
1074	      return {
1075	        duplicate: true,
1076	        header: this.poHeader(req.poId, existed),
1077	        lines: existed.resultLines,
1078	        repeatedFrom: this.repeatedPoSource(req.poId),
1079	      };
1080	    }
1081	
1082	    for (const pid of req.items.keys()) {
1083	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
1084	    }
1085	
1086	    const ordered: Record<string, number> = nullProto();
1087	    const reportLines: string[] = [];
1088	    for (const pid of [...req.items.keys()].sort()) {
1089	      const qty = req.items.get(pid)!;
1090	      ordered[pid] = qty;
1091	      reportLines.push(`订购 ${pid} x${qty}，待到货 ${qty}`);
1092	    }
1093	
1094	    this.pos[req.poId] = {
1095	      poId: req.poId, supplier: req.supplier, wh: req.wh, ordered, resultLines: reportLines,
1096	    };
1097	    this.newPoIds.push(req.poId);
1098	
1099	    return { duplicate: false, header: this.poHeader(req.poId, this.pos[req.poId]), lines: reportLines };
1100	  }
1101	
1102	  private poHeader(poId: string, rec: PurchaseRecord): string {
1103	    return `采购单 ${poId} 登记成功，供应商 ${rec.supplier}，收货仓 ${rec.wh}，共 ${Object.keys(rec.ordered).length} 种商品（登记不改动库存）：`;
1104	  }
1105	
1106	  /**
1107	   * 采购到货：独立到货单编号，引用已登记采购单，可分次收部分商品；
1108	   * 仅能收采购单内商品，并入采购单收货仓。各商品“未冲销累计到货 + 本次”
1109	   * 不得超过订购量；任一明细非法、超收或库存溢出整单拒绝。
1110	   * 到货单与入库/出库/调拨/盘点/冲销单共用唯一编号空间；普通入库不能绑定采购。
1111	   */
1112	  applyArrival(req: ArrivalRequest): ApplyOutcome {
1113	    const existed = this.arrivals[req.arrId];
1114	    if (existed !== undefined) {
1115	      if (
1116	        existed.poId !== req.poId ||
1117	        stableStringify(existed.qty) !== stableStringify(canonicalArrivalItems(req.items))
1118	      )
1119	        throw new BizError(`到货单编号 ${req.arrId} 已用于内容不同的单据，拒绝提交`);
1120	      return {
1121	        duplicate: true,
1122	        header: this.arrivalHeader(req.arrId, existed),
1123	        lines: existed.resultLines,
1124	        repeatedFrom: this.repeatedArrivalSource(req.arrId),
1125	      };
1126	    }
1127	    // 与入库/出库/调拨/盘点/取消/冲销单共用唯一编号空间（采购单编号空间独立，不在此列）
1128	    if (this.docs[req.arrId] !== undefined)
1129	      throw new BizError(`单据编号 ${req.arrId} 已用于入库/出库/调拨/盘点单，拒绝提交`);
1130	    if (this.revs[req.arrId] !== undefined)
1131	      throw new BizError(`单据编号 ${req.arrId} 已用于冲销单，拒绝提交`);
1132	    if (this.cancels[req.arrId] !== undefined)
1133	      throw new BizError(`单据编号 ${req.arrId} 已用于取消单，拒绝提交`);
1134	
1135	    const po = this.pos[req.poId];
1136	    if (po === undefined) throw new BizError(`采购单 ${req.poId} 不存在，拒绝到货`);
1137	
1138	    for (const [pid] of req.items) {
1139	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
1140	      if (po.ordered[pid] === undefined)
1141	        throw new BizError(`商品 ${pid} 不在采购单 ${req.poId} 的订购明细内，拒绝整单`);
1142	    }
1143	
1144	    const arrivedBefore = this.effectiveArrived(req.poId); // 未冲销累计到货
1145	    const cancelledBefore = this.effectiveCancelled(req.poId); // 未冲销累计取消
1146	    const pids = [...req.items.keys()].sort();
1147	    const wh = po.wh;
1148	
1149	    // 超收与溢出先整单校验、模拟，任一商品失败则不登记任何到货
1150	    const reportLines: string[] = [];
1151	    const planned = new Map<string, { before: number; after: number; qty: number }>();
1152	
1153	    for (const pid of pids) {
1154	      const qty = req.items.get(pid)!;
1155	      const cancelled = cancelledBefore[pid] ?? 0;
1156	      const cumulative = (arrivedBefore[pid] ?? 0) + qty; // 含本次的未冲销累计到货
1157	      // 待到货量 = 订购量 - 有效到货量 - 有效取消量；本次到货只能使用扣除有效取消后的待到货量
