1656	   */
1657	  private applyCancelReversal(revId: string, origId: string, origCan: CancelRecord): ApplyOutcome {
1658	    if (this.reversedOrigs.has(origId)) {
1659	      let existingRev = '';
1660	      for (const [r, rec] of Object.entries(this.revs)) {
1661	        if (rec.orig === origId) {
1662	          existingRev = r;
1663	          break;
1664	        }
1665	      }
1666	      throw new BizError(`取消原单 ${origId} 已被冲销单 ${existingRev} 成功冲销，每张取消单只能冲销一次`);
1667	    }
