1669	    const poId = origCan.poId;
1670	    const po = this.pos[poId];
1671	    const pids = Object.keys(origCan.qty).sort();
1672	    const arrived = this.effectiveArrived(poId); // 未冲销累计到货（不受取消冲销影响）
1673	    const cancelledBefore = this.effectiveCancelled(poId); // 含本取消单：其尚未被冲销，仍计入
