1687	    // 登记冲销关系（该取消单自此不计入有效取消）；由 commit 一次性落库
1688	    this.revs[revId] = { orig: origId, resultLines: reportLines };
1689	    this.newRevIds.push(revId);
1690	    this.reversedOrigs.add(origId);
1691	
1692	    return {
1693	      duplicate: false,
1694	      header: `冲销单 ${revId} 提交成功，冲销取消原单 ${origId}（采购单 ${poId}），共 ${pids.length} 种商品：`,
1695	      lines: reportLines,
