1790	function formatEntry(e: LedgerEntry): string {
1791	  let line: string;
1792	  if (e.type === 'count' || e.type === 'count-rev') {
1793	    const applied = e.type === 'count' ? e.diff! : -e.diff!; // 冲销盘点应用反向差额
1794	    line =
1795	      `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}` +
1796	      `\t差额=${fmtSigned(applied)}\t${e.before}->${e.after}\t账面=${e.expected}\t实盘=${e.actual}`;
1797	  } else {
1798	    let signed: string;
1799	    // 符号必须与前后余量一致：入库/冲销出库/到货/调入方向为增，其余为减
1800	    const increases =
1801	      e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' ||
1802	      ((e.type === 'transfer' || e.type === 'transfer-rev') &&
1803	        (e.type === 'transfer') === (e.wh === e.to));
1804	    signed = `${increases ? '+' : '-'}${e.qty}`;
1805	    line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
1806	    if (e.type === 'transfer' || e.type === 'transfer-rev') line += `\t调拨=${e.from}->${e.to}`;
1807	    if (e.po !== undefined) line += `\t采购单=${e.po}`;
1808	  }
1809	  if (e.orig !== undefined) line += `\t原单=${e.orig}`;
1810	  return line;
1811	}
