1866	/** 计算采购单各商品的有效（未冲销）到货量、有效（未冲销）取消量与待到货量。 */
1867	function purchaseProgress(store: Store, poId: string): {
1868	  effective: Record<string, number>;
1869	  cancelled: Record<string, number>;
1870	  remaining: Record<string, number>;
1871	} {
1872	  const effective = nullProto<Record<string, number>>();
1873	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
1874	    if (arr.poId !== poId) continue;
1875	    const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
1876	    if (isReversed) continue;
1877	    for (const [pid, q] of Object.entries(arr.qty)) effective[pid] = (effective[pid] ?? 0) + q;
1878	  }
1879	  const cancelled = nullProto<Record<string, number>>();
1880	  for (const [canId, can] of Object.entries(store.cancels)) {
1881	    if (can.poId !== poId) continue;
1882	    const isReversed = Object.values(store.reversals).some((r) => r.orig === canId);
1883	    if (isReversed) continue;
1884	    for (const [pid, q] of Object.entries(can.qty)) cancelled[pid] = (cancelled[pid] ?? 0) + q;
1885	  }
1886	  const po = store.purchases[poId];
1887	  const remaining = nullProto<Record<string, number>>();
1888	  for (const [pid, ordered] of Object.entries(po.ordered)) {
1889	    remaining[pid] = ordered - (effective[pid] ?? 0) - (cancelled[pid] ?? 0);
1890	  }
1891	  return { effective, cancelled, remaining };
1892	}
