1894	/**
1895	 * 单商品采购状态。无取消时保持原有展示（未到货/部分到货/收齐）；
1896	 * 有取消时区分仍待收与已结清：待到货为零但含取消的结清不报“收齐”，
1897	 * 取消永远不计作到货。
1898	 */
1899	function poStatus(ordered: number, effective: number, cancelled = 0): string {
1900	  const remaining = ordered - effective - cancelled;
1901	  if (cancelled === 0) {
1902	    if (effective === 0) return '未到货';
1903	    if (remaining > 0) return '部分到货';
1904	    return '收齐';
1905	  }
1906	  if (remaining > 0) return effective === 0 ? '未到货（仍待收）' : '部分到货（仍待收）';
1907	  return effective === ordered ? '收齐' : '已结清（含取消）';
1908	}
