2071	/**
2072	 * 整批导入：按列表顺序在同一份草稿上处理各项，后项可见前项生效结果；
2073	 * 任一项失败整批拒绝（此前已保存的单据不撤销，本批任何变动均不落库）。
2074	 * 全部重复时不改写数据。逐项输出编号、首次生效/重复（及重复来源）状态与提交结果。
2075	 */
2076	function runImport(rest: string[], dataDir: string): void {
2077	  const args = parseArgs(rest, ['--file']);
2078	  const file = args.flags['--file'];
2079	  if (file === undefined || args.positionals.length > 0)
2080	    throw new UsageError('用法：import --file <单据列表 JSON 文件>');
2081	
2082	  // 先完整读取并解析文件：文件不可读/解析失败时绝不触碰已提交状态
2083	  const requests = parseImportFile(readImportFile(file));
2084	
2085	  // 参数与文件格式均确认无误后才打开本地数据；损坏数据在此被拒绝且不报告成功
2086	  const store = loadStore(dataDir);
2087	  const ledger = new Ledger(store);
2088	  // 模拟阶段收集输出：只有整批通过并完成保存后才向用户报告，绝不报告部分成功
2089	  const blocks: string[] = [];
2090	  let newCount = 0;
2091	
2092	  requests.forEach((r, i) => {
2093	    const pos = `第 ${i + 1}/${requests.length} 项`;
2094	    // 模拟阶段的业务拒绝同样标注列表位置与原因
2095	    const apply = (): ApplyOutcome => {
2096	      switch (r.kind) {
2097	        case 'doc': return ledger.applyDoc(r.req);
2098	        case 'count': return ledger.applyCount(r.req);
2099	        case 'reverse': return ledger.applyReversal(r.docId, r.orig);
2100	        case 'po': return ledger.applyPurchase(r.req);
2101	        case 'arrival': return ledger.applyArrival(r.req);
2102	        case 'cancel': return ledger.applyCancel(r.req);
2103	      }
2104	    };
2105	    let outcome: ApplyOutcome;
2106	    try {
2107	      outcome = apply();
2108	    } catch (e) {
2109	      if (e instanceof BizError) throw new BizError(`第 ${i + 1} 项：${e.message}`);
2110	      throw e;
2111	    }
2112	    const id =
2113	      r.kind === 'reverse' ? r.docId
2114	      : r.kind === 'po' ? r.req.poId
2115	      : r.kind === 'arrival' ? r.req.arrId
2116	      : r.kind === 'cancel' ? r.req.canId
2117	      : r.req.docId;
2118	
2119	    let status: string;
2120	    if (outcome.duplicate) {
2121	      const where = outcome.repeatedFrom === 'batch' ? '（本批此前已出现）' : '（导入前已存在）';
2122	      status = `重复${where}，返回原提交结果，不重新核对库存、不追加流水`;
2123	    } else {
2124	      status = '首次生效';
2125	      newCount++;
2126	    }
2127	    blocks.push([`[${pos}] 单据 ${id}：${status}`, outcome.header, ...outcome.lines].join('\n'));
2128	  });
2129	
2130	  // 全部项通过：有新生效单据时整批一次性保存；全部重复则不改写数据
2131	  ledger.commit(dataDir);
2132	
2133	  console.log(`整批导入完成：共 ${requests.length} 项，首次生效 ${newCount} 项，重复 ${requests.length - newCount} 项。`);
2134	  for (const block of blocks) console.log(block);
2135	}
